/// <summary>
/// An extension class for GUPPricingRuleConditionCopy table.
/// </summary>
[ExtensionOf(tableStr(GUPPricingRuleConditionCopy))]
internal final class METGUPPricingRuleConditionCopy_Extension
{
}

Method.Source:
/// <summary>
/// Method to determine if the attribute is linked to SalesTable or SalesLine when external sales data is used.
/// </summary>
/// <param name = "_attributeSource">Enum element from GUPPricingAttributeSource, either a SalesLine or SalesTable as attribute source</param>
/// <returns>Boolean true, if the attribute source passed as parameter matches with the selcted attriubte to be set with value on Edit price attributes form, else false</returns>
public boolean metIsAttributeSource(GUPPricingAttributeSource _attributeSource)
{
    boolean ret;
    GUPPricingAttributeLink pricingAttributeLink = this.priceAttributeLink();

    if (pricingAttributeLink.Source == _attributeSource)
    {
        ret = true;
    }

    return ret;
}

/// <summary>
/// Method to determine and validate if the attribute is linked to SalesTable or SalesLine when external sales data is used.
/// </summary>
/// <param name = "_attributeSource">Enum element from GUPPricingAttributeSource, either a SalesLine or SalesTable as attribute source</param>
/// <param name = "_tamRebateDeal">Record of TAMRebateDeal table </param>
/// <param name = "_tamRebateTable">Record of TAMRebateTable</param>
/// <returns>Boolean false if the validation passes, else true</returns>
public boolean metValidatePricingRuleConditionValue(GUPPricingAttributeSource _attributeSource, TAMRebateDeal _tamRebateDeal, TAMRebateTable _tamRebateTable)
{
    boolean ret = true;
    TAMRebateDeal tamRebateDeal = _tamRebateDeal;

    if (!_tamRebateDeal)
    {
        tamRebateDeal = TAMRebateDeal::find(_tamRebateTable.RebateDeal);
    }

    if (tamRebateDeal.METUseExternalSellData == NoYes::Yes
        && this.metIsAttributeSource(_attributeSource)
        && _tamRebateTable.PriceComponentCombination)
    {
        ret = checkFailed("@MET:METExternalSalesDataSOError");
    }

    return ret;
}

/// <summary>
/// Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
/// Exclusion treated as AND condition, so when ConditionValue is set, METisOR should be set to No.
/// Inclusion treated as OR condition, so when ConditionValue is set, METisOR should be set to Yes.
/// It is ok not to check the if rebate is customer or vendor. Vendor rebate don't have header attributes and preview
/// </summary>
public void update()
{
    if (TAMRebateParameters::find().METUseOrAttributes
    &&  this.ConditionValue)
    {
        if (strContains(this.conditionValue, '!'))
        {
            this.METisOR = NoYes::No;
        }
        else
        {
            this.METisOR = NoYes::Yes;
        }
    }
    else
    {
        this.METisOR = NoYes::No;
    }

    next update();
}
